-- public.pier_refusal(p_world uuid, p_x integer, p_y integer, p_deck integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.pier_refusal(p_world uuid, p_x integer, p_y integer, p_deck integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare g record; v_plant text;
begin
  select * into g from pier_ground(p_world, p_x, p_y);
  if not exists (select 1 from stone_bed s where s.tile = g.tile) then
    return 'Piers need bare ground or flat growth: clear the tile first.';
  end if;
  select water_plant_word(p.kind) into v_plant from water_plant p where p.world_id = p_world and p.x = p_x and p.y = p_y;
  if v_plant is not null then return 'Pull up the ' || v_plant || ' first.'; end if;
  if g.high > p_deck then
    return 'Ground rises to ' || metres(g.high) || ' m, above the deck at ' || metres(p_deck) || ' m'
      || ': plan from the highest tile.';
  end if;
  if g.water is not null and g.water - g.low > pier_water() then
    return 'Water ' || metres(g.water - g.low) || ' m deep; piers stand in '
      || metres(pier_water()) || ' m at most.';
  end if;
  if g.water is not null and p_deck < g.water + pier_clear() then
    return 'Water at ' || metres(g.water) || ' m, deck at ' || metres(p_deck) || ' m'
      || ': deck must clear water by ' || metres(pier_clear()) || ' m.';
  end if;
  if p_deck - g.low > pier_drop() then
    return 'Ground falls ' || metres(p_deck - g.low) || ' m under the deck; piers span '
      || metres(pier_drop()) || ' m at most.';
  end if;
  return null;
end $function$
